using System;
using System.IO;
using System.Collections.Generic;
using System.Media;
partial class Shelf {
 Dictionary<string,SoundPlayer> sounds=new Dictionary<string,SoundPlayer>();List<MemoryStream> soundStreams=new List<MemoryStream>();DateTime lastMoveSound=DateTime.MinValue;bool audioReady=false;
 void InitAudio(){foreach(var player in sounds.Values)player.Dispose();sounds.Clear();foreach(var stream in soundStreams)stream.Dispose();soundStreams.Clear();if(testMode)return;try{foreach(string name in new[]{"move","confirm","back","favorite","remove","switch","launch"}){var stream=new MemoryStream(Synthesize(name,options.SoundVolume,options.SoundStyle));soundStreams.Add(stream);var player=new SoundPlayer(stream);player.Load();sounds[name]=player;}audioReady=true;}catch{audioReady=false;}}
 void PlayUi(string name){if(testMode||!options.SoundEnabled||!audioReady||closing)return;if(name=="move"){if((DateTime.UtcNow-lastMoveSound).TotalMilliseconds<85)return;lastMoveSound=DateTime.UtcNow;}try{if(sounds.ContainsKey(name)){var player=sounds[name];System.Threading.ThreadPool.QueueUserWorkItem(o=>{try{player.Play();}catch{}});}}catch{}}
 static byte[] Synthesize(string kind,double volume,string style="柔和电子"){int rate=44100;double[] notes;double spacing,duration,gain;
  switch(kind){case "confirm":notes=new[]{659.255,987.767};spacing=.055;duration=.21;gain=.16;break;case "favorite":notes=new[]{554.365,698.456,830.609,1108.73};spacing=.055;duration=.41;gain=.16;break;case "remove":notes=new[]{659.255,493.883};spacing=.075;duration=.29;gain=.13;break;case "back":notes=new[]{739.989,554.365};spacing=.055;duration=.22;gain=.12;break;case "switch":notes=new[]{587.33,783.991};spacing=.045;duration=.19;gain=.12;break;case "launch":notes=new[]{261.626,391.995,523.251,659.255,783.991};spacing=.105;duration=.98;gain=.18;break;default:notes=new[]{880.0};spacing=0;duration=.065;gain=.10;break;}
  if(style=="温暖木音"){duration*=.9;spacing*=.9;}else if(style=="街机像素"){duration*=.8;spacing*=.8;}
  int count=(int)(duration*rate);var pcm=new short[count];volume=Math.Max(0,Math.Min(1,volume));for(int i=0;i<count;i++){double t=(double)i/rate,value=0;for(int n=0;n<notes.Length;n++){double local=t-n*spacing;if(local<0)continue;double sustain=kind=="launch"?.43:kind=="move"?.035:.13;double env=(1-Math.Exp(-local/.004))*Math.Exp(-local/sustain);double frequency=notes[n];double wave=Math.Sin(2*Math.PI*frequency*local)+.15*Math.Sin(2*Math.PI*frequency*2*local)*Math.Exp(-local/.07)+.055*Math.Sin(2*Math.PI*frequency*3*local)*Math.Exp(-local/.035);if(style=="水晶清音"){frequency*=1.35;wave=Math.Sin(2*Math.PI*frequency*local)+.23*Math.Sin(2*Math.PI*frequency*2.76*local)*Math.Exp(-local/.07);}else if(style=="温暖木音"){frequency*=.75;wave=Math.Sin(2*Math.PI*frequency*local)+.28*Math.Sin(2*Math.PI*frequency*2*local)*Math.Exp(-local/.025);env*=Math.Exp(-local/.12);}else if(style=="街机像素"){wave=0;for(int harmonic=1;harmonic<=7;harmonic+=2)wave+=Math.Sin(2*Math.PI*frequency*harmonic*local)/(harmonic*harmonic);wave*=.85;}else if(style=="科幻脉冲"){double phase=2*Math.PI*frequency*(local+.0015*(1-Math.Exp(-local/.025)));wave=Math.Sin(phase)+.17*Math.Sin(phase*.5)*Math.Exp(-local/.08);}value+=wave*env;}
   value/=Math.Sqrt(notes.Length);double fade=Math.Min(1,(duration-t)/.025);value*=gain*volume*fade;pcm[i]=(short)(Math.Tanh(value)*32700);}
  using(var ms=new MemoryStream())using(var writer=new BinaryWriter(ms)){writer.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));writer.Write(36+count*2);writer.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));writer.Write(16);writer.Write((short)1);writer.Write((short)1);writer.Write(rate);writer.Write(rate*2);writer.Write((short)2);writer.Write((short)16);writer.Write(System.Text.Encoding.ASCII.GetBytes("data"));writer.Write(count*2);foreach(short sample in pcm)writer.Write(sample);return ms.ToArray();}
 }
 void OpenAudio(){NewModal("audio","界面音效","选择风格即时试听 · 不影响游戏本身的声音");ModalRow("pad",options.SoundEnabled?"音效已开启":"音效已关闭","确认切换开关",()=>{options.SoundEnabled=!options.SoundEnabled;Save();PlayUi("confirm");OpenAudio();},options.SoundEnabled);ModalLabel("音效风格");foreach(string preset in new[]{"柔和电子","水晶清音","温暖木音","街机像素","科幻脉冲"}){string choice=preset;ModalRow("spark",choice,"确认切换并试听",()=>{options.SoundStyle=choice;Save();InitAudio();OpenAudio();PlayUi("favorite");},options.SoundStyle==choice);}ModalLabel("音量");foreach(var item in new[]{new[]{"轻柔","0.3"},new[]{"标准","0.55"},new[]{"清晰","0.85"}}){string name=item[0];double value=double.Parse(item[1],System.Globalization.CultureInfo.InvariantCulture);ModalRow("spark",name,"音量档位",()=>{options.SoundVolume=value;Save();InitAudio();PlayUi("favorite");OpenAudio();},Math.Abs(options.SoundVolume-value)<.01);}}
 void CloseAudio(){foreach(var sound in sounds.Values)sound.Dispose();foreach(var stream in soundStreams)stream.Dispose();sounds.Clear();soundStreams.Clear();}
}

